CONTINUITY = [
 ('maintenance_review','Review the plan that fits now','Review one current responsibility in this program and decide whether its size still fits your circumstances. Keep what helps and change what has become burdensome.','Choose one task to keep;Simplify one task or leave it;Choose your next review point'),
 ('year_one_reflection','Look back without a grade','You may use this reflection around a personal anniversary or whenever it feels useful. Notice practical changes without assigning a score, declaring recovery, or requiring a positive story.','Name one change you want to notice;Record a need that remains;Choose whether to save or skip this reflection'),
 ('year_two_adjustment','Make room for a new season','A plan from an earlier period may no longer fit. Revisit one of your program-specific priorities without repeating onboarding or treating changed needs as lost progress.','Choose one earlier priority;Describe what has changed for you;Keep, revise or retire one next step'),
 ('long_term_checkin','Use a lighter check-in','Long-term support can be brief. Use one of this program’s practical themes to check what you want help with now, rather than completing an accumulating backlog.','Choose one current theme;Name a small question or action;Leave other themes for another time'),
 ('support_reset','Review who helps and what is shared','Support arrangements can change over time. Review the people and purposes you have actually agreed to, keeping private records separate and seeking confirmation before new sharing.','Choose one existing support arrangement;Review its purpose and your current preference;Change or end sharing through the available controls if you choose'),
 ('return_after_pause','Return from where you are','You can return to this program after a pause without catching up on missed exercises. Choose a present need and an appropriately small action.','Name what matters now in this program;Choose one small step or simply review;Discard an outdated task if you want')
]

def build():
    packs=[]
    for slug,p in PACKS.items():
        rows=[r.split('|') for r in p['rows'].splitlines() if r.strip()]
        assert len(rows)==24 and all(len(r)==3 for r in rows), slug
        items=[]
        for i,(title,context,steps) in enumerate(rows):
            actions=steps.split(';')
            section=p['sections'][min(len(p['sections'])-1,i*len(p['sections'])//24)]
            body=f'{context}\n\nTry one step, or stop here:\n'+'\n'.join(f'{j+1}. {step}.' for j,step in enumerate(actions))
            items.append({'content_key':f'launch-20261030-{slug}-{i+1:02d}', 'section':section, 'title':title, 'intro_text':context, 'body_text':body, 'actions':actions, 'suggested_choices':['Try one step','Ask for help','Save for later','Skip this activity'], 'reflection_prompt':f'For “{title}”, what would you like to keep, change or leave undecided?', 'low_energy_action':actions[0], 'estimated_minutes':5, 'sequence':i+1, 'cadence':'participant_selected', 'day_number':None, 'status':'draft', 'source_ids':p['sources'], 'evidence_status':'Original Lellee exercise; design informed by the listed general principles; not independently validated.'})
        for j,(key,title,context,steps) in enumerate(CONTINUITY):
            anchor=rows[(j*4)%24][0]
            context=f'{context} In {p["name"]}, you might revisit “{anchor}” or choose another topic. {p["principle"]}'
            actions=steps.split(';')
            items.append({'content_key':f'launch-20261030-{slug}-{key}', 'section':'Continuity and optional review', 'title':title, 'intro_text':context, 'body_text':context+'\n\n'+'\n'.join(f'{i+1}. {step}.' for i,step in enumerate(actions)), 'actions':actions, 'suggested_choices':['Keep','Adapt','Pause','Seek appropriate support'], 'reflection_prompt':f'What would make your {p["name"]} plan more workable now?', 'low_energy_action':actions[0], 'estimated_minutes':5, 'sequence':25+j, 'cadence':key, 'day_number':None, 'status':'draft', 'source_ids':p['sources'], 'evidence_status':'Original design proposal; cadence does not establish a clinical or outcome timeline.'})
        packs.append({'slug':slug,'name':p['name'],'status':'draft','public_release':False,'service_scope':'coaching_and_personal_organization','sections':p['sections'],'section_semantics':'Optional nonlinear themes; not clinical stages or performance levels. Existing approved Wave 1 section names are preserved.','principle':p['principle'],'minimum_care_recipients':3 if slug=='caregiving' else None,'audience':'adults','items':items})
    out={'schema_version':1,'version':'launch-preparation-2026-10-30','status':'draft','approved_portfolio':['recovery','reentry','caregiving','independent-living','housing-stability','grief','workforce-reentry','family-recovery'],'recovery_content':'Existing published Recovery content is unchanged.','publication_authorized':False,'review_statement':'Prepared for content and technical review, not clinical validation or publication. Source principles do not establish that these exercises work. Higher-risk questions are referred outside coaching; no legal, medical, benefits-eligibility, emergency-assessment or placement advice is supplied.','sources':SOURCES,'packs':packs}
    DEST.mkdir(parents=True,exist_ok=True)
    (DEST/'program-packs.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'packs':len(packs),'original_core_exercises':168,'continuity_templates':42,'total_items':210,'published_items':0}))

if __name__=='__main__': build()
